using UnityEngine;
public class ColonyClimber : MonoBehaviour { public float attachRange = 1.15f; public float probeRadius = 0.12f; public float stickSpeed = 0.35f; public float wallNormalY = 0.55f; public float alignSpeed = 12f; public Transform visual; CharacterController body; float defaultSlope = 45f; float defaultStep = 0.3f; public bool Climbing { get; private set; } public Vector3 SurfaceNormal { get; private set; } = Vector3.up; public string PositionWriter => "controller"; public void Release() { Climbing = false; SurfaceNormal = Vector3.up; ApplyClimbLimits(false); if (visual != null) { visual.localRotation = Quaternion.identity; } } void Awake() { body = GetComponent<CharacterController>(); if (body != null) { defaultSlope = body.slopeLimit; defaultStep = body.stepOffset; } if (visual == null) { var child = transform.Find("Visual"); visual = child != null ? child : null; } } public bool MoveTowards(Vector3 destination, float speed, ref float verticalVelocity, float gravity) { Vector3 to = destination - transform.position; if (to.sqrMagnitude < 0.0001f) { ReleaseIfGrounded(); return Climbing; } Vector3 wish = to.normalized; if (!Climbing && to.y < 0.8f) { ApplyClimbLimits(false); AlignVisual(Vector3.up); return false; } if (!RefreshWall(wish) || !Climbing) { ApplyClimbLimits(false); AlignVisual(Vector3.up); return false; } Vector3 tangent = Vector3.ProjectOnPlane(to, SurfaceNormal); if (tangent.sqrMagnitude < 0.02f) { tangent = Vector3.ProjectOnPlane(Vector3.up, SurfaceNormal); } Vector3 vel = tangent.normalized * speed + SurfaceNormal * stickSpeed; verticalVelocity = 0f; ApplyClimbLimits(true); Slide(vel * Time.deltaTime); AlignVisual(SurfaceNormal); ReleaseIfGrounded(); if (!Climbing) ApplyClimbLimits(false); return Climbing; } public bool PlayerClimb(Vector3 planarWish, float speed, bool jumping, ref float velocityY) { if (planarWish.sqrMagnitude < 0.04f && !Climbing) { return false; } Vector3 probe = planarWish.sqrMagnitude > 0.04f ? planarWish.normalized : transform.forward; if (jumping && Climbing) { Climbing = false; velocityY = 4.2f; ApplyClimbLimits(false); AlignVisual(Vector3.up); return false; } if (!RefreshWall(probe) || !Climbing) { ApplyClimbLimits(false); AlignVisual(Vector3.up); return false; } if (Vector3.Dot(probe, -SurfaceNormal) < 0.18f && Vector3.Dot(planarWish.normalized, Vector3.up) < 0.2f) { Climbing = false; ApplyClimbLimits(false); AlignVisual(Vector3.up); return false; } Vector3 alongWall = Vector3.ProjectOnPlane(planarWish, SurfaceNormal); Vector3 upWall = Vector3.ProjectOnPlane(Vector3.up, SurfaceNormal); if (upWall.sqrMagnitude < 0.01f) { upWall = Vector3.up; } float intoWall = Vector3.Dot(probe, -SurfaceNormal); float climb = Mathf.Max(intoWall, Vector3.Dot(planarWish, Vector3.up) + 0.35f); Vector3 vel = alongWall * speed + upWall.normalized * speed * Mathf.Clamp01(climb + 0.65f) + SurfaceNormal * stickSpeed; velocityY = 0f; ApplyClimbLimits(true); Slide(vel * Time.deltaTime); AlignVisual(SurfaceNormal); ReleaseIfGrounded(); if (!Climbing) ApplyClimbLimits(false); return Climbing; } bool RefreshWall(Vector3 wish) { Vector3 origin = transform.position + Vector3.up * 0.38f; Vector3 search = Climbing ? -SurfaceNormal : wish; if (search.sqrMagnitude < 0.0001f) { search = transform.forward; } if (Probe(origin, search, Climbing ? 1.1f : attachRange, out RaycastHit hit)) { Climbing = true; SurfaceNormal = hit.normal; return true; } if (!Climbing) { Climbing = false; SurfaceNormal = Vector3.up; return false; } Vector3[] dirs = { transform.forward, -transform.forward, transform.right, -transform.right, wish }; for (int i = 0; i < dirs.Length; i++) { if (dirs[i].sqrMagnitude < 0.0001f) { continue; } if (Probe(origin, dirs[i], attachRange, out hit)) { SurfaceNormal = hit.normal; return true; } } Climbing = false; SurfaceNormal = Vector3.up; return false; } bool Probe(Vector3 origin, Vector3 dir, float range, out RaycastHit hit) { hit = default; if (dir.sqrMagnitude < 0.0001f) { return false; } var hits = Physics.SphereCastAll(origin, probeRadius, dir.normalized, range, ~0, QueryTriggerInteraction.Ignore); float best = float.MaxValue; bool found = false; for (int i = 0; i < hits.Length; i++) { var h = hits[i]; if (h.collider == null || h.collider.transform.IsChildOf(transform) || h.collider.GetComponentInParent<ColonyHealth>() != null) { continue; } if (!IsClimbable(h) || h.distance >= best) { continue; } best = h.distance; hit = h; found = true; } return found; } void ReleaseIfGrounded() { if (Climbing && body != null && body.isGrounded && Vector3.Dot(SurfaceNormal, Vector3.up) > 0.72f) { Climbing = false; SurfaceNormal = Vector3.up; AlignVisual(Vector3.up); } } void Slide(Vector3 delta) { if (body == null) { transform.position += delta; return; } body.enabled = false; transform.position += delta; body.enabled = true; } void ApplyClimbLimits(bool climbing) { if (body == null) { return; } body.slopeLimit = climbing ? 90f : defaultSlope; body.stepOffset = climbing ? 0.9f : defaultStep; } bool IsClimbable(RaycastHit hit) { if (hit.normal.sqrMagnitude < 0.01f || Mathf.Abs(hit.normal.y) >= wallNormalY) { return false; } var col = hit.collider; if (col == null) { return false; } float tall = col.bounds.size.y; return tall >= 1.6f; } void AlignVisual(Vector3 up) { if (visual == null) { return; } Vector3 fwd = Vector3.ProjectOnPlane(transform.forward, up); if (fwd.sqrMagnitude < 0.001f) { fwd = Vector3.ProjectOnPlane(Vector3.forward, up); } if (fwd.sqrMagnitude < 0.001f) { return; } visual.rotation = Quaternion.Slerp(visual.rotation, Quaternion.LookRotation(fwd.normalized, up), Time.deltaTime * alignSpeed); } }